suppressMessages({library(dplyr); library(readr); library(ggplot2); library(tidyr)})

.ROOT <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), ".."))
  else getwd()
})
PROJECT   <- .ROOT
WKBD_ROOT <- normalizePath(file.path(PROJECT, "..", ".."))
source(file.path(WKBD_ROOT, "data_workspace_2026-07", "figure_house_theme.R"))

d <- read_csv(file.path(WKBD_ROOT, "online_appendix/ch3_backbench_frontbench_full_1979_2025.csv"),
              show_col_types = FALSE) |>
  arrange(year)

# ============================================================
# FIGURE — house style
# ============================================================
CANVAS_W <- house_width_in()

long_d <- d |>
  select(year, backbench_ratio, frontbench_ratio) |>
  pivot_longer(-year, names_to = "group", values_to = "ratio") |>
  mutate(group = recode(group, backbench_ratio = "Backbench", frontbench_ratio = "Frontbench"))

p <- ggplot(long_d, aes(year, ratio, linetype = group)) +
  geom_line(colour = "#000000", linewidth = 0.8) +
  geom_point(colour = "#000000", size = 0.9) +
  annotate("text", x = 1982, y = 0.475, label = "Frontbench", colour = "grey35",
           fontface = "italic", size = mm_for(PRINTED$caption, CANVAS_W)) +
  annotate("text", x = 1988, y = 0.383, label = "Backbench", colour = "grey35",
           fontface = "italic", size = mm_for(PRINTED$caption, CANVAS_W)) +
  scale_linetype_manual(values = c("Backbench" = "solid", "Frontbench" = "dashed")) +
  scale_x_continuous(breaks = seq(1980, 2020, 5), limits = c(1979, 2025)) +
  scale_y_continuous(labels = scales::percent_format(accuracy = 1)) +
  guides(linetype = "none") +
  labs(
    title = paste0(
      "Figure 3.3: Self-regarding speech, backbench vs\n",
      "frontbench, House of Commons, 1979-2025"
    ),
    x = NULL, y = "Self-regarding ratio (mean)"
  ) +
  house_print(CANVAS_W)

OUT <- file.path(PROJECT, "figures/fig_3_3_hansard_self_regarding.png")
ggsave(OUT, p, width = CANVAS_W, height = CANVAS_W * 0.58, dpi = HOUSE_DPI, bg = "white")
cat("Figure saved:", OUT, "\n")

# ============================================================
# FOOTNOTE NOTES — generated so numbers cannot drift from the figure
# ============================================================
period <- function(d, y0, y1, col) d |> filter(year >= y0, year <= y1) |> summarise(m = mean({{col}}, na.rm = TRUE)) |> pull(m)

p1_bb <- period(d, 1979, 1988, backbench_ratio); p1_fb <- period(d, 1979, 1988, frontbench_ratio)
p2_bb <- period(d, 1989, 1997, backbench_ratio); p2_fb <- period(d, 1989, 1997, frontbench_ratio)
p3_bb <- period(d, 1998, 2009, backbench_ratio); p3_fb <- period(d, 1998, 2009, frontbench_ratio)
p4_bb <- period(d, 2010, 2019, backbench_ratio); p4_fb <- period(d, 2010, 2019, frontbench_ratio)
p5_bb <- period(d, 2020, 2025, backbench_ratio); p5_fb <- period(d, 2020, 2025, frontbench_ratio)
fb_share_early <- d$fb_share[d$year == 1979]; fb_share_late <- d$fb_share[d$year == 2025]

